import { useState } from "react";
import axios from "axios";
import { useDropzone } from "react-dropzone";

const API="http://127.0.0.1:8000";

export default function App(){
  const [user,setUser]=useState("");
  const [pass,setPass]=useState("");
  const [logged,setLogged]=useState(false);
  const [file,setFile]=useState(null);

  const login=async()=>{
    const f=new FormData();
    f.append("username",user);
    f.append("password",pass);
    const res=await axios.post(API+"/login",f);
    if(res.data.ok) setLogged(true);
  };

  const onDrop=(files)=>setFile(files[0]);
  const {getRootProps,getInputProps}=useDropzone({onDrop});

  const send=async()=>{
    const f=new FormData();
    f.append("sender",user);
    f.append("receiver","user2");
    f.append("file",file);
    await axios.post(API+"/send",f);
  };

  const read=async(id)=>{
    const res=await axios.get(API+"/read",{params:{msg_id:id},responseType:"blob"});
    const url=window.URL.createObjectURL(new Blob([res.data]));
    const a=document.createElement("a");
    a.href=url;
    a.download="file";
    a.click();
  };

  if(!logged){
    return(
      <div style={{padding:40}}>
        <h2>Login</h2>
        <input onChange={e=>setUser(e.target.value)}/>
        <input type="password" onChange={e=>setPass(e.target.value)}/>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return(
    <div style={{padding:40}}>
      <h2>SecureVault</h2>

      <div {...getRootProps()} style={{border:"2px dashed gray",padding:20}}>
        <input {...getInputProps()}/>
        Drag & Drop File
      </div>

      <button onClick={send}>Send</button>
    </div>
  );
}
